  clone.querySelectorAll('button,.btn,.icon-btn,.modal').forEach(function(el){el.remove();});
  clone.querySelectorAll('[contenteditable]').forEach(function(el){el.removeAttribute('contenteditable');});
  // textarea 的当前值不在 innerHTML 里，需手动写入
  clone.querySelectorAll('textarea').forEach(function(el){
    var v=el.value||el.getAttribute('data-init')||'';
    el.textContent=v;el.removeAttribute('placeholder');
  });
  /* 图片相对路径修正：预览用 iframe srcdoc/新窗口没有基准路径，相对 src 会加载失败。
     将克隆内所有相对路径图片与内联背景图统一转为绝对地址；data:/blob: 图片保持原样。 */
  function absUrl(s){ if(!s)return s; if(/^(data:|blob:|http:|https:|file:|\/)/i.test(s))return s; try{return new URL(s,location.href).href;}catch(e){return s;} }
  clone.querySelectorAll('img').forEach(function(im){ var s=im.getAttribute('src'); if(s)im.setAttribute('src',absUrl(s)); });
  clone.querySelectorAll('[style]').forEach(function(el){
    ['background','backgroundImage'].forEach(function(p){
      var v=el.style.getPropertyValue(p);
      if(v&&/url\(/i.test(v)){
        var nv=v.replace(/url\(\s*(['"]?)((?!data:|blob:|https?:|\/).+?)\1\s*\)/gi,function(m,q,u){return 'url("'+absUrl(u.replace(/["']/g,''))+'")';});
        el.style.setProperty(p,nv);
      }
    });
  });
  var style='<style>@page{margin:12mm 10mm}/* ===== 全局基础 ===== */*{box-sizing:border-box}body{font-family:-apple-system,"PingFang SC","Microsoft YaHei","Noto Sans SC",sans-serif;color:#2E2A24;line-height:1.82;font-size:15px;padding:0;margin:0;background:#FCF8EC}/* ===== 页面标题区 ===== */.page-head{margin-bottom:20px;padding:18px 20px;background:linear-gradient(135deg,#6E4F37 0%,#4A3427 100%);color:#fff;border-radius:14px;box-shadow:0 4px 16px rgba(122,115,99,.18)}.page-head h1{font-size:23px;margin:0 0 8px;color:#fff;display:flex;align-items:center;gap:9px;white-space:nowrap}.page-head h1 svg{width:26px;height:26px;flex-shrink:0;filter:brightness(0) invert(1)}.page-head p{color:rgba(255,255,255,.78);margin:0;font-size:14.5px;line-height:1.65}/* ===== 网格布局 ===== */.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}/* ===== 卡片容器（每个区块都有边框+圆角+阴影） ===== */.card{border:1.5px solid #DAD5C6;border-radius:13px;padding:20px;margin-bottom:18px;break-inside:avoid;background:#fff;box-shadow:0 2px 8px rgba(44,52,64,.05),0 .5px 1px rgba(44,52,64,.03);position:relative;overflow:hidden}.card::before{content:"";position:absolute;top:0;left:0;width:4px;height:100%;background:linear-gradient(180deg,#6E4F37,#8A6D48);border-radius:13px 0 0 13px}/* ===== 标题 ===== */.card h3{font-size:17.5px;color:#4A3427;margin:0 0 14px;font-weight:700;padding-bottom:10px;border-bottom:1.5px dashed #EFE8D8;display:flex;align-items:center;gap:7px;white-space:nowrap}.card h3:first-child{margin-top:0}.card h4{font-size:16px;color:#4A3427;margin:14px 0 10px;font-weight:700}/* ===== 段落与文字 ===== */.card p{font-size:15px;line-height:1.85;margin:10px 0;color:#3A4038}/* ===== 列表（带装饰性项目符号和分隔线） ===== */.card ul,.card ol{margin:12px 0;padding-left:0;list-style:none}.card ul>li,.card ol>li{position:relative;padding:10px 12px 10px 30px;margin:6px 0;font-size:15px;line-height:1.8;color:#3A4038;border:1px solid #EFE8D8;border-radius:9px;background:#FCF8EC;transition:.15s}.card ul>li::before{content:"";position:absolute;left:11px;top:50%;transform:translateY(-50%);width:7px;height:7px;border-radius:50%;background:#6E4F37;flex-shrink:0}.card ol>li{counter-increment:list-num;padding-left:32px}.card ol>li::before{content:counter(list-num);position:absolute;left:10px;top:50%;transform:translateY(-50%);width:22px;height:22px;border-radius:50%;background:#6E4F37;color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;line-height:1}.card ol{counter-reset:list-num}/* ===== 嵌套列表 ===== */.card ul ul,.card ol ol{margin:6px 0 0 12px}.card ul ul>li,.card ol ol>li{padding:7px 10px 7px 24px;margin:4px 0;font-size:14px;border-color:#EFE8D8;background:#fff}/* ===== Callout 提示框（更醒目） ===== */.callout{border-radius:11px;padding:16px 18px;margin-top:14px;font-size:15px;line-height:1.78;background:linear-gradient(135deg,#EFE8D8,#F5EFE2);border:1.5px solid #E2D8C4;border-left:5px solid #6E4F37;color:#4A5D2E;box-shadow:0 2px 6px rgba(122,115,99,.08)}/* ===== 标签 ===== */.tag{border:1.5px solid #D2CCBC;border-radius:999px;padding:4px 14px;font-size:13px;color:#4A3427;background:#EEF1E5;font-weight:500;display:inline-block;margin:2px 3px}/* ===== 输入框/文本域 ===== */.textarea,.card textarea{width:100%;border:1.5px solid #DAD5C6;border-radius:10px;padding:13px 14px;font-size:15px;line-height:1.75;font-family:inherit;white-space:pre-wrap;min-height:100px;color:#2E2A24;background:#FDFBF7;transition:.15s}textarea{resize:none}/* ===== 表格（斑马纹+粗表头） ===== */table{border-collapse:separate;border-spacing:0;width:100%;font-size:14px;border:1.5px solid #DAD5C6;border-radius:10px;overflow:hidden}.card table{margin:12px 0}th,td{border:1px solid #E1DCCE;padding:10px 8px;text-align:center;line-height:1.55}th{background:linear-gradient(180deg,#4A3427,#4A3427);color:#fff;font-weight:700;font-size:13.5px;letter-spacing:.3px}tr:nth-child(even) td{background:#EFE8D8}td{color:#3A4038}/* ===== SVG 图标 ===== */svg{max-width:24px;max-height:24px}/* ===== 分隔线装饰 ===== */hr,.divider{border:none;height:1.5px;background:linear-gradient(90deg,transparent,#DAD5C6 20%,#DAD5C6 80%,transparent);margin:16px 0}/* ===== 报告品牌头/页脚 ===== */.pdf-brandbar{display:flex;align-items:center;gap:14px;background:linear-gradient(135deg,#4A3427 0%,#4A3427 45%,#6E4F37 100%);color:#fff;padding:16px 22px;border-radius:14px;margin-bottom:22px;box-shadow:0 6px 18px rgba(74,58,40,.22);position:relative;overflow:hidden;page-break-inside:avoid}.pdf-brandbar::after{content:"";position:absolute;right:-40px;top:-40px;width:160px;height:160px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.14),transparent 62%)}.pb-logo{flex-shrink:0;z-index:1;width:40px;height:40px;border-radius:9px;background:linear-gradient(135deg,#8A6D48,#6E4F37);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:20px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.2)}.pb-logo::before{display:none}.pb-logo img{width:100%;height:100%;border-radius:9px;display:block}.pb-info{display:flex;flex-direction:column;min-width:0;z-index:1}.pb-info b{font-size:18px;letter-spacing:.5px}.pb-info span{font-size:12px;opacity:.82;margin-top:3px}.pb-meta{margin-left:auto;text-align:right;z-index:1;display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0}.pb-meta .pb-name{font-size:13px;opacity:.92;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.3);padding:6px 16px;border-radius:999px;white-space:nowrap;min-width:80px;text-align:center;flex-shrink:0}.pb-meta .pb-date{font-size:11.5px;opacity:.8}.pdf-footer{margin-top:28px;padding-top:18px;border-top:1.5px dashed #BAB5A6;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:12px;line-height:1.8;color:#8C7863;text-align:center;page-break-inside:avoid}.pdf-footer div{background:#EFE8D8;border-radius:999px;padding:6px 16px}.pdf-brandbar,.pdf-footer{-webkit-print-color-adjust:exact;print-color-adjust:exact}@page{size:A4;margin:13mm 11mm}/* ===== 打印隐藏 ===== */@media print{.no-print{display:none!important}}/* ===== 手机端适配 ===== */@media(max-width:600px){body{font-size:15.5px;padding:0 4px}.page-head{padding:14px 16px;border-radius:11px}.page-head h1{font-size:21px}.page-head h1 svg{width:22px;height:22px}.page-head p{font-size:14px}.grid{grid-template-columns:1fr;gap:12px}.card{padding:16px 14px;margin-bottom:14px;border-radius:11px}.card h3{font-size:16.5px;padding-bottom:8px}.card h4{font-size:15.5px}.card p,.card ul>li,.card ol>li,.callout,.textarea,.card textarea{font-size:14.5px}.card ul>li,.card ol>li{padding:9px 10px 9px 26px}.tag{font-size:12.5px;padding:3px 11px}table{font-size:13px}th,td{padding:8px 6px}}</style>';
  var nowD=new Date(),taskList=document.querySelector('.view.active')?null:'';
  var ds=(''+nowD.getFullYear())+'-'+('0'+(nowD.getMonth()+1)).slice(-2)+'-'+('0'+nowD.getDate()).slice(-2);
