var movieIdx=-1;
function nextMovieQuote(){movieIdx++;renderMovieQuote();}
function renderMovieQuote(){
  var el=document.getElementById('movieQuote');if(!el)return;
  if(movieIdx<0){var day=Math.floor(Date.now()/86400000);movieIdx=day%MOVIE_QUOTES.length;}
  var m=MOVIE_QUOTES[movieIdx%MOVIE_QUOTES.length];
  el.innerHTML='<div style="font-size:17px;font-weight:600;line-height:1.7;margin-bottom:12px;text-align:center">「'+m.q+'」</div>'+
    '<div style="text-align:center;font-size:12px;color:var(--muted);margin-bottom:14px">—— '+m.src+' · '+m.scene+'</div>'+
    '<div style="font-size:13px;color:var(--text);line-height:1.8;background:var(--bg);padding:10px 12px;border-radius:8px;border-left:3px solid var(--primary);margin-bottom:8px"><strong style="color:var(--primary)">解读 · </strong>'+m.e+'</div>'+
    '<div style="font-size:13px;color:var(--text);line-height:1.8;background:var(--teal-light);padding:10px 12px;border-radius:8px;border-left:3px solid var(--teal)"><strong style="color:var(--teal)">用在哪 · </strong>'+m.apply+'</div>';
}
function getMovies(){return DB.get('movies',[]);}
function saveMovies(a){DB.set('movies',a);}
function renderMovies(){
  var box=document.getElementById('movieNoteList');if(!box)return;
  var ms=getMovies();
  if(!ms.length){box.innerHTML='<p style="color:var(--hint);font-size:13px">还没有观影笔记 · 看完一部电影或剧，用三栏写一篇</p>';return;}
  box.innerHTML=ms.slice(-8).reverse().map(function(m,i){
    return '<div style="padding:10px;border:1px solid var(--border);border-radius:8px;margin-bottom:8px">'+
      '<div style="display:flex;justify-content:space-between;align-items:center"><span style="font-weight:600;font-size:13px;color:var(--primary)">'+escapeHtml(m.title)+'</span>'+
      '<button class="btn btn-sm" style="font-size:10px;padding:2px 6px;color:var(--hint)" onclick="delMovie('+i+')">删除</button></div>'+
      '<div style="font-size:12px;color:var(--muted);margin-top:4px;white-space:pre-wrap">'+escapeHtml(m.note)+'</div>'+
      '<div style="font-size:11px;color:var(--hint);margin-top:4px">'+m.date+'</div></div>';
  }).join('');
}
function addMovie(){
  var t=document.getElementById('movieTitle'),n=document.getElementById('movieNote');
  if(!t||!t.value.trim()||!n||!n.value.trim()){uiAlert('请填写片名和笔记内容');return;}
  var ms=getMovies();ms.push({title:t.value.trim(),note:n.value.trim(),date:todayKey()});
  saveMovies(ms);
  t.value='';n.value='';
  renderMovies();flash('观影笔记已保存');
}
function delMovie(i){var ms=getMovies();ms.splice(i,1);saveMovies(ms);renderMovies();}


