      return '<a href="'+m.plat[p]+'" target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:4px 12px;border-radius:999px;font-size:11px;font-weight:600;text-decoration:none;margin:2px 4px 2px 0;'+
        (p==='哔哩哔哩'?'background:#FB729920;color:#FB7299;border:1px solid #FB729950':p==='爱奇艺'?'background:#00BE0620;color:#00BE06;border:1px solid #00BE0650':p==='优酷'?'background:#1989FA20;color:#1989FA;border:1px solid #1989FA50':p==='腾讯视频'?'background:#FF602220;color:#FF6022;border:1px solid #FF602250':'background:#FFB80020;color:#B88600;border:1px solid #FFB80050')+
        '">▶ '+p+'</a>';
