/* ── 习惯养成 ── */
var TAG_COLORS=['#4A3427','#6E4F37','#8A6A2D','#A9803F','#C9A24E','#A87F3C','#9A7348','#B45309'];
function getHabits(){return DB.get('habits',[
  {name:'📖 背单词30个',icon:'📖',streak:0,lastDate:'',records:{}},
  {name:'🏃 运动30分钟',icon:'🏃',streak:0,lastDate:'',records:{}},
  {name:'😴 23:30前睡觉',icon:'😴',streak:0,lastDate:'',records:{}},
  {name:'📖 阅读30分钟',icon:'📖',streak:0,lastDate:'',records:{}},
  {name:'✍️ 写复盘日记',icon:'✍️',streak:0,lastDate:'',records:{}}
]);}
function saveHabits(h){DB.set('habits',h);}
function renderHabits(){
  var habits=getHabits();
  var box=document.getElementById('habitList');
  if(!box)return;
  var today=todayKey();
  box.innerHTML=habits.map(function(h,i){
    var done=h.records[today]===true;
    return '<div class="habit-item'+(done?' done':'')+'" id="habit-'+i+'">'+
      '<div class="habit-check'+(done?' checked':'')+'" onclick="toggleHabit('+i+')">'+(done?'✓':'')+'</div>'+
      '<div class="habit-info"><div class="habit-name">'+escapeHtml(h.name)+'</div>'+
      '<div class="habit-streak">'+(h.streak>0?'🔥 连续 '+h.streak+' 天':'还未开始')+(((h.focus||0)>0)?' · 🧠专注 '+h.focus:'')+'</div></div>'+
      '<button class="btn btn-sm habit-del" style="font-size:11px;padding:2px 8px;color:var(--coral);flex-shrink:0;margin-left:auto;background:transparent;border:1px solid var(--border)" onclick="delHabit('+i+')" title="删除该习惯">✕ 删</button>'+
    '</div>';
  }).join('');
  refreshPomoHabitOpts();
}
function toggleHabit(i){
  var habits=getHabits();
  if(!habits[i])return;
  var today=todayKey();
  var prevDay=yesterdayKey();
  if(habits[i].records[today]===true){
    delete habits[i].records[today];
    // 回退连续天数
    if(habits[i].lastDate===today)habits[i].lastDate=prevDay;
    habits[i].streak=Math.max(0,calcStreak(habits[i]));
  }else{
    habits[i].records[today]=true;
    habits[i].lastDate=today;
    habits[i].streak=calcHabitStreak(habits[i]);
  }
  saveHabits(habits);renderHabits();renderHabitHeatmap();updateStats();
}
function calcHabitStreak(habit){
  var streak=0;
  var d=new Date();
  while(true){
    var key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    if(habit.records[key]===true){streak++;d.setDate(d.getDate()-1);}
    else break;
  }
  return streak;
}
function yesterdayKey(){
  var d=new Date();d.setDate(d.getDate()-1);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function addHabit(){
  var n=document.getElementById('newHabitName');
  var ic=document.getElementById('newHabitIcon');
  if(!n||!n.value.trim()){flash('请输入习惯名称');return;}
  var habits=getHabits();
  habits.push({name:(ic?ic.value:'📖')+' '+n.value.trim(),icon:ic?ic.value:'📖',streak:0,lastDate:'',records:{}});
  saveHabits(habits);renderHabits();renderHabitHeatmap();updateStats();refreshHomeStats();refreshPomoHabitOpts();
  n.value='';
  flash('已添加习惯');
}
function delHabit(i){
  var habits=getHabits();
  if(!habits[i])return;
  var name=habits[i].name||'该习惯';
  uiConfirm('要移除「'+name+'」吗？已记录的打卡数据也会一并清走。',function(){
    habits.splice(i,1);
    saveHabits(habits);renderHabits();renderHabitHeatmap();updateStats();refreshHomeStats();refreshPomoHabitOpts();
    flash('该条习惯已移除');
  });
}
function renderHabitHeatmap(){
  var habits=getHabits();
  var box=document.getElementById('habitHeatmap');
  if(!box)return;
  var days=[];
  for(var i=41;i>=0;i--){
    var d=new Date();d.setDate(d.getDate()-i);
    var key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    var doneCount=habits.filter(function(h){return h.records[key]===true;}).length;
    var ratio=habits.length>0?doneCount/habits.length:0;
    var lvl=0;
    if(ratio>0&&ratio<0.25)lvl=1;
    else if(ratio>=0.25&&ratio<0.5)lvl=2;
    else if(ratio>=0.5&&ratio<0.75)lvl=3;
    else if(ratio>=0.75)lvl=4;
    days.push('<div class="heat-cell heat-'+lvl+'" title="'+key+'（'+doneCount+'/'+habits.length+' 个习惯）"></div>');
  }
  box.innerHTML='<div class="heat-grid" style="grid-template-columns:repeat(7,1fr)">'+days.join('')+'</div>'+
    '<div style="display:flex;justify-content:space-between;margin-top:6px;font-size:10px;color:var(--hint)">'+
    '<span>6周前</span><span>今天</span></div>';
  /* 本周 / 本月坚持概况 */
  var tbox=document.getElementById('habitTotals');
  if(tbox&&habits.length){
    var wk=0,wkT=7*habits.length,mo=0,moT=30*habits.length;
    for(var w=0;w<7;w++){var wd=new Date();wd.setDate(wd.getDate()-w);wk+=wkHit(habits,wd);}
    for(var m=0;m<30;m++){var md=new Date();md.setDate(md.getDate()-m);mo+=wkHit(habits,md);}
    var wkPct=Math.round(wk/wkT*100),moPct=Math.round(mo/moT*100);
    tbox.innerHTML='<span style="font-size:12px;color:var(--text)">本周坚持率 <b style="color:var(--teal)">'+wkPct+'%</b> <span style="color:var(--hint)">('+wk+'/'+wkT+')</span></span>'+
      '<span style="font-size:12px;color:var(--muted)">｜</span>'+
      '<span style="font-size:12px;color:var(--text)">近30天 <b style="color:var(--primary)">'+moPct+'%</b> <span style="color:var(--hint)">('+mo+'/'+moT+')</span></span>';
  } else if(tbox){tbox.innerHTML='';}
}
function wkHit(habits,d){
  var key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  return habits.filter(function(h){return h.records[key]===true;}).length;
}

