/* ── 成长档案统计 ── */
/* 首开日期：应用一打开就同步记录（仅首次写入，绝不覆盖已存值），
   保证「使用天数/成长档案」从用户第一次打开那天起算，而非进入统计页时才起算 */
function ensureFirstUseDate(){
  try{
    if(!localStorage.getItem('pp_firstUseDate')){
      var n=new Date();
      var k=n.getFullYear()+'-'+('0'+(n.getMonth()+1)).slice(-2)+'-'+('0'+n.getDate()).slice(-2);
      localStorage.setItem('pp_firstUseDate',k);
    }
    return localStorage.getItem('pp_firstUseDate');
  }catch(e){return null;}
}
/* 同步执行：页面一加载完成首开日期的记录 */
(function(){ try{ ensureFirstUseDate(); }catch(e){} })();
function getFirstUseDate(){ var d=DB.get('firstUseDate',null); if(d)return d; return ensureFirstUseDate(); }
/* 连续天数计算（用于习惯最长连续 / 番茄最长连续天序） */
function longestStreakFromRecords(records){
  var keys=(records&&typeof records==='object')?Object.keys(records).filter(function(k){return records[k];
  }).sort():[];
  if(!keys.length)return 0;
  var best=1,cur=1,prev=new Date(keys[0]+'T00:00:00');
  for(var i=1;i<keys.length;i++){
    var d=new Date(keys[i]+'T00:00:00');
    if(Math.round((d-prev)/86400000)===1){cur++;}else{cur=1;}
    if(cur>best)best=cur;
    prev=d;
  }
  return best;
}
function longestConsecutiveDays(map){
  var keys=(map&&typeof map==='object')?Object.keys(map).filter(function(k){return (map[k]||0)>0;
  }).sort():[];
  if(!keys.length)return 0;
  var best=1,cur=1,prev=new Date(keys[0]+'T00:00:00');
  for(var i=1;i<keys.length;i++){
    var d=new Date(keys[i]+'T00:00:00');
    if(Math.round((d-prev)/86400000)===1){cur++;}else{cur=1;}
    if(cur>best)best=cur;
    prev=d;
  }
  return best;
}
/* 成长档案 · 一切统计都从这里实时算出：日历跨度只作下限，重点统计「有实际操作行为」的真实数据 */
function updateStats(){
  var first=getFirstUseDate();
  if(!first){first=todayKey();}
  var tasks=DB.get('tasks',[])||[];
  var habits=getHabits();
  var checkins=DB.get('checkins',{})||{};
  var pomos=DB.get('pomoCount',{})||{};
  var goals1=DB.get('goalChecks',{})||{};
  var goals2=DB.get('goal100',{})||{};

  /* 1) 真实有效使用天数：只要某天有打卡/完成待办/番茄/目标等任意操作即算一天 */
  var activeDays={};
  function addDay(k){ if(k)activeDays[k]=1; }
  tasks.forEach(function(t){ if(t.done) addDay(t.doneDate||t.date); });
  habits.forEach(function(h){ var r=h.records||{}; Object.keys(r).forEach(function(rk){ if(r[rk]) addDay(rk); }); });
  function cntCheckins(c){ for(var k in c){ var day=c[k]; if(day&&typeof day==='object'){ var n=0; for(var x in day){ if(day[x])n++; } if(n>0)addDay(k);} else if(day){ addDay(k);} } }
  cntCheckins(checkins);
  Object.keys(pomos).forEach(function(k){ if((pomos[k]||0)>0) addDay(k); });
  function cntGoals(g){ for(var k in g){ if(g[k])addDay(k); } }
  cntGoals(goals1); cntGoals(goals2);
  if(first)addDay(String(first));
  var days=Math.max(1,Object.keys(activeDays).length);
  setEl('statDays',days);

  /* 2) 累计完成任务：勾选为「已完成」的待办数量 */
  var done=0; tasks.forEach(function(t){ if(t.done)done++; });
  setEl('statTasksDone',done);

  /* 3) 习惯最长连续打卡：从逐日记录算最长连续，而非只看当前 streak */
  var maxStreak=0;
  habits.forEach(function(h){ var s=longestStreakFromRecords(h.records||{}); if(s>maxStreak)maxStreak=s; });
  setEl('statStreak',maxStreak);

  /* 4) 番茄总数 + 最长连续番茄天序 */
  var totalPomo=0; Object.keys(pomos).forEach(function(k){totalPomo+=pomos[k]||0;});
  setEl('statPomos',totalPomo);
  setEl('statPomoStreak',longestConsecutiveDays(pomos));

  /* 里程碑：始于首次打开 · 实时刷新陪伴天数 */
  try{
    var _fu=getFirstUseDate();
    var _g=document.getElementById('growthSince');
    if(_fu&&_g){
      var _dstart=new Date(_fu+'T00:00:00');
      var _dtoday=new Date(); _dtoday.setHours(0,0,0,0);
      var _computed=Math.round((_dtoday-_dstart)/86400000)+1;
      _g.innerHTML='<span style="display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:30px;height:30px;border-radius:50%;background:linear-gradient(135deg,#fef3c7,#fde68a);color:#8A6A2D;font-size:15px">🌱</span>'+
        '<span><b style="color:var(--text)">你的栖匣之旅始于 '+_fu+'</b> · 从<strong style="color:var(--primary)">第一次打开</strong>就自动开始记录，之后所有记录与数据都保存在本机、实时同步、不会因升级而消失 · 至今已陪伴你 <b style="color:var(--primary)">'+_computed+'</b> 天</span>';
    }
  }catch(e){}

  /* 实时同步时间戳 */
  try{
    var _st=document.getElementById('growthLiveStamp');
    if(_st){ var n=new Date(); _st.textContent='实时统计 · 更新于 '+String(n.getMonth()+1).padStart(2,'0')+'月'+String(n.getDate()).padStart(2,'0')+'日 '+String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0'); }
  }catch(e){}

  renderAchievements();
  renderWeeklyTrend();
  renderGrowthInsight(days,done,totalPomo,maxStreak);
}
function setEl(id,val){var el=document.getElementById(id);if(el)el.textContent=val;}

