/* ── 本周打卡趋势（自然周 · 每周自动切换 · 支持查看历史周快照）
   数据源合并：① 习惯打卡完成记录 ② 标记为「已完成」的今日待办。两类共同计入本周完成任务。 */
var _weekOffset=0;
function setWeekOffset(o){_weekOffset=o;renderWeeklyTrend();}
function dKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function renderWeeklyTrend(){
  var box=document.getElementById('weeklyActivity');
  if(!box)return;
  var now=new Date();
  var curMon=new Date(now);curMon.setHours(0,0,0,0);curMon.setDate(curMon.getDate()-((curMon.getDay()+6)%7));
  var mon=new Date(curMon);mon.setDate(mon.getDate()+_weekOffset*7);
  var sun=new Date(mon);sun.setDate(mon.getDate()+6);
  var tasks=DB.get('tasks',[])||[];
  var habits=getHabits();

  var byDay={};
  for(var i=0;i<7;i++){var dd=new Date(mon);dd.setDate(mon.getDate()+i);byDay[dKey(dd)]={h:0,t:0};}
  habits.forEach(function(h){var r=h.records||{};for(var k in r){if(r[k]&&byDay[k])byDay[k].h++;}});
  tasks.forEach(function(t){if(t.done){var kk=t.doneDate||t.date;if(byDay[kk])byDay[kk].t++;}});

  var weekH=0,weekT=0;for(var wk in byDay){weekH+=byDay[wk].h;weekT+=byDay[wk].t;}
  var weekTotal=weekH+weekT;
  var labels=['一','二','三','四','五','六','日'];
  var head='<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:10px">'+
    '<div style="font-size:13px;font-weight:600;color:var(--text)">'+( _weekOffset===0?'本周':'历史周')+' · '+mon.getMonth()+1+'月'+mon.getDate()+'日 ~ '+sun.getMonth()+1+'月'+sun.getDate()+'日</div>'+
    '<div style="display:flex;gap:6px;flex-wrap:wrap">'+
      '<button class="btn btn-sm" onclick="setWeekOffset('+(_weekOffset-1)+')" title="查看上一周">‹ 上周</button>'+
      '<button class="btn btn-sm" onclick="setWeekOffset(0)" '+( _weekOffset===0?'disabled style="opacity:.45"':'')+'>回到本周</button>'+
      '<button class="btn btn-sm" onclick="setWeekOffset('+(_weekOffset+1)+')" title="查看下一周">下周 ›</button>'+
    '</div></div>';

  if(weekTotal===0){
    box.innerHTML=head+'<div style="padding:26px 12px;text-align:center;color:var(--hint);font-size:13px;line-height:1.9">'+
      '这一周还没有打卡或完成的任务<br><span style="font-size:12px">到「今日概览」打个卡、勾选一件待办，这里会自动出现你的变化。</span></div>';
    return;
  }

  var maxVal=1;for(var j=0;j<7;j++){var dq=new Date(mon);dq.setDate(mon.getDate()+j);var bq=byDay[dKey(dq)];var vv=(bq?bq.h+bq.t:0);if(vv>maxVal)maxVal=vv;}
  var bars=[];
  for(var j2=0;j2<7;j2++){
    var d2=new Date(mon);d2.setDate(mon.getDate()+j2);var key2=dKey(d2);
    var b2=byDay[key2]||{h:0,t:0};var v=b2.h+b2.t;var pct=Math.round(v/maxVal*100);
    var isToday=dKey(new Date())===key2;
    bars.push('<div style="display:flex;flex-direction:column;align-items:center;flex:1 0 auto;min-width:34px;gap:4px">'+
      '<div style="font-size:11px;color:var(--text);font-weight:600">'+v+'</div>'+
      '<div title="'+key2+'（打卡 '+b2.h+' 次 · 完成待办 '+b2.t+' 件）" style="width:26px;height:'+Math.max(pct,6)+'px;background:linear-gradient(to top,'+(isToday?'#4f8a72,#2f6f57':'#c9a24e,#8a6a2d')+');border-radius:4px 4px 0 0;min-height:6px;box-shadow:0 1px 3px rgba(0,0,0,.12)"></div>'+
      '<span style="font-size:10px;color:var(--hint)">'+(isToday?'今天':'周'+labels[j2])+'</span></div>');
  }
  box.innerHTML=head+
    '<div style="display:flex;align-items:flex-end;gap:6px;height:150px;padding:0 4px;overflow-x:auto">'+bars.join('')+'</div>'+
    '<div style="display:flex;flex-wrap:wrap;gap:8px 16px;justify-content:center;margin-top:10px;font-size:11px;color:var(--muted)">'+
      '<span style="display:inline-flex;align-items:center;gap:5px"><i style="width:11px;height:11px;border-radius:3px;background:linear-gradient(to top,#c9a24e,#8a6a2d);display:inline-block"></i>习惯打卡</span>'+
      '<span style="display:inline-flex;align-items:center;gap:5px"><i style="width:11px;height:11px;border-radius:3px;background:linear-gradient(to top,#4f8a72,#2f6f57);display:inline-block"></i>完成待办</span>'+
      '<span style="display:inline-flex;align-items:center;gap:5px;color:var(--text);font-weight:600">合计 '+weekTotal+'（打卡 '+weekH+' · 待办 '+weekT+'）</span></div>'+
    '<div style="margin-top:6px;font-size:11px;color:var(--hint);text-align:center">已完成任务 = 习惯打卡 + 已完成的待办，两项合并计入</div>';
}

