function renderGrowthInsight(days,tasks,pomos,streak){
  var box=document.getElementById('growthInsight');
  if(!box)return;
  var insights=[];
  if(days>=1&&days<7)insights.push('🎉 你刚开始使用栖匣！坚持一周就能看到变化。建议先从<strong>每日打卡</strong>和<strong>番茄专注</strong>两个功能开始。');
  if(days>=7)insights.push('📅 你已经坚持使用 <strong>'+days+'</strong> 天了！超过80%的人会在第一周放弃，你已经超越了他们。');
  if(tasks>=10)insights.push('✅ 已完成 <strong>'+tasks+'</strong> 个任务！执行力在稳步提升。继续保持"今日只定一件事"的习惯。');
  if(pomos>=10)insights.push('🍅 累计 <strong>'+pomos+'</strong> 个番茄钟！深度专注是最好的投资。');
  if(streak>=7)insights.push('🔥 最长连续打卡 <strong>'+streak+'</strong> 天！习惯的力量正在显现。');
  if(streak>=30)insights.push('🏆 <strong>30天连续打卡</strong>成就解锁！这已经不是习惯，而是生活方式了。');
  if(insights.length===0)insights.push('💡 开始使用各项功能后，这里会出现专属于你的成长洞察。先去打个卡吧！');
  box.innerHTML=insights.join('<br><br>');
}

